/**
 * Shared Igloohome duration (hourly) AlgoPIN helper with collision-safe variance
 * allocation.
 *
 * Hourly AlgoPIN is the bridge-down fallback. The algorithm is deterministic:
 * the same deviceId + startDate + endDate + variance always yields the same
 * code. Igloo allows 3 variances (1-3) per exact duration (start AND end).
 *
 * startDate is floored to the UTC hour; endDate is ceiled to the next UTC hour
 * so we never cut a rental short. Duration must be 1–672 hours.
 *
 * Collision guarantee: a partial unique index on
 * `rental_access_codes (lock_id, start_time, end_time, variance)
 *  WHERE status = 'active'` is the source of truth. The pre-insert query is an
 * optimization only. A concurrent race is handled by catching unique-violation
 * (23505) and retrying the next free variance.
 */

import {
  ALGOPIN_HOURLY_MAX_HOURS,
  ALGOPIN_HOURLY_MIN_HOURS,
  formatAlgoPinEndIso,
  formatAlgoPinStartIso,
} from "./pinTiming.ts";

export const IGLOOHOME_ALGOPIN_API_BASE_URL = "https://api.igloodeveloper.co/igloohome";

const MIN_VARIANCE = 1;
const MAX_VARIANCE = 3;

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

async function readResponse(res: Response) {
  const text = await res.text();
  try {
    return { text, json: text ? JSON.parse(text) : null };
  } catch {
    return { text, json: null };
  }
}

type IglooAlgoPinResponse =
  | { success: true; pin: string; pinId: string }
  | { success: false; error: string; rawResponse?: unknown };

async function requestHourlyAlgoPinFromIgloo(
  accessToken: string,
  lockId: string,
  startDate: string,
  endDate: string,
  variance: number,
  accessName: string,
): Promise<IglooAlgoPinResponse> {
  const res = await fetch(`${IGLOOHOME_ALGOPIN_API_BASE_URL}/devices/${lockId}/algopin/hourly`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({ accessName, startDate, endDate, variance }),
  });
  const body = await readResponse(res);
  if (!res.ok && res.status !== 201) {
    return {
      success: false,
      error: `Hourly AlgoPIN failed with status ${res.status}`,
      rawResponse: body.json ?? body.text,
    };
  }
  const pin = String(body.json?.pin || body.json?.access_code || body.json?.code || body.json?.data?.pin || "");
  if (!pin) {
    return { success: false, error: "Hourly AlgoPIN succeeded but no PIN value in response", rawResponse: body.json };
  }
  return { success: true, pin, pinId: String(body.json?.pinId || body.json?.id || "") };
}

/**
 * Variances already claimed by other *active* hourly AlgoPINs on this lock for
 * this exact (hour-aligned) start+end duration. Optimization only.
 */
async function usedVariances(
  supabase: SupabaseClient,
  lockId: string,
  startDate: string,
  endDate: string,
): Promise<Set<number>> {
  const { data, error } = await supabase
    .from("rental_access_codes")
    .select("variance")
    .eq("lock_id", lockId)
    .eq("start_time", startDate)
    .eq("end_time", endDate)
    .eq("status", "active")
    .not("variance", "is", null);
  if (error) {
    console.warn("[algoPin] Failed to query used variances, trying full 1-3 range:", error.message);
    return new Set();
  }
  return new Set(
    (data ?? [])
      .map((row: { variance: number | null }) => Number(row.variance))
      .filter((v: number) => Number.isFinite(v)),
  );
}

function isUniqueViolation(error: { code?: string; message?: string } | null | undefined): boolean {
  if (!error) return false;
  if (error.code === "23505") return true;
  return /duplicate key value violates unique constraint/i.test(error.message || "");
}

export type CreateAlgoPinWithVarianceOptions = {
  supabase: SupabaseClient;
  accessToken: string;
  lockId: string;
  /** Raw ISO start; floored to the top of the UTC hour before use. */
  startDate: string;
  /** Raw ISO end; ceiled to the next UTC hour before use. */
  endDate: string;
  accessName: string;
  /**
   * Remaining `rental_access_codes` columns for the insert (order_id,
   * customer_email, status, etc). Do not include `access_pin`, `pin_id`,
   * `pin_type`, `lock_id`, `variance`, `start_time`, or `end_time` — this
   * helper fills those in.
   */
  insertRow: Record<string, unknown>;
};

export type CreateAlgoPinWithVarianceResult =
  | {
    success: true;
    exhausted: false;
    pin: string;
    pinId: string;
    variance: number;
    startDate: string;
    endDate: string;
    kind: "hourly";
    /** rental_access_codes.id (uuid) of the inserted row. */
    rowId: string | null;
    error?: undefined;
  }
  | {
    success: false;
    /**
     * True when every variance slot (1-3) for this lock + duration is
     * already claimed. Callers should fall back to the bridge path rather
     * than treat this as a hard failure.
     */
    exhausted: boolean;
    error: string;
  };

/**
 * Create a duration (hourly) AlgoPIN using an unused variance (1-3) for this
 * lock + exact start/end, and persist it to `rental_access_codes` in the same
 * call (the insert is what lets us detect and retry past a collision race).
 *
 * Returns `exhausted: true` (not a hard failure) when all 3 variances are
 * already active for this lock + duration.
 */
export async function createAlgoPinWithVariance(
  opts: CreateAlgoPinWithVarianceOptions,
): Promise<CreateAlgoPinWithVarianceResult> {
  const { supabase, accessToken, lockId, accessName, insertRow } = opts;
  const startDate = formatAlgoPinStartIso(opts.startDate);
  const endDate = formatAlgoPinEndIso(opts.endDate);

  const startMs = new Date(startDate).getTime();
  const endMs = new Date(endDate).getTime();
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
    return {
      success: false,
      exhausted: false,
      error: `Hourly AlgoPIN window is invalid (start=${startDate}, end=${endDate})`,
    };
  }
  const hours = (endMs - startMs) / (60 * 60 * 1000);
  if (hours < ALGOPIN_HOURLY_MIN_HOURS || hours > ALGOPIN_HOURLY_MAX_HOURS) {
    return {
      success: false,
      exhausted: false,
      error:
        `Hourly AlgoPIN duration ${hours}h is outside ${ALGOPIN_HOURLY_MIN_HOURS}–${ALGOPIN_HOURLY_MAX_HOURS} hours`,
    };
  }

  const used = await usedVariances(supabase, lockId, startDate, endDate);
  const candidates: number[] = [];
  for (let v = MIN_VARIANCE; v <= MAX_VARIANCE; v++) {
    if (!used.has(v)) candidates.push(v);
  }

  if (candidates.length === 0) {
    return {
      success: false,
      exhausted: true,
      error:
        `All ${MAX_VARIANCE} hourly AlgoPIN variance slots are already active for lock ${lockId} ${startDate}→${endDate}`,
    };
  }

  const { end_time: _ignoredEnd, start_time: _ignoredStart, ...insertRest } = insertRow;

  let lastError = "";
  for (const variance of candidates) {
    const algo = await requestHourlyAlgoPinFromIgloo(
      accessToken,
      lockId,
      startDate,
      endDate,
      variance,
      accessName,
    );
    if (!algo.success) {
      return { success: false, exhausted: false, error: algo.error };
    }

    const { data: inserted, error: insertError } = await supabase
      .from("rental_access_codes")
      .insert({
        ...insertRest,
        access_pin: algo.pin,
        pin_id: algo.pinId || "",
        pin_type: "algopin",
        lock_id: lockId,
        variance,
        start_time: startDate,
        end_time: endDate,
      })
      .select("id")
      .single();

    if (!insertError) {
      return {
        success: true,
        exhausted: false,
        pin: algo.pin,
        pinId: algo.pinId,
        variance,
        startDate,
        endDate,
        kind: "hourly",
        rowId: inserted?.id ?? null,
      };
    }

    if (isUniqueViolation(insertError)) {
      console.warn(
        `[algoPin] Variance ${variance} lost the race for lock ${lockId} ${startDate}→${endDate} — retrying next slot`,
      );
      lastError = insertError.message;
      continue;
    }

    return { success: false, exhausted: false, error: insertError.message };
  }

  return {
    success: false,
    exhausted: true,
    error: lastError ||
      `All available hourly AlgoPIN variance slots collided for lock ${lockId} ${startDate}→${endDate}`,
  };
}

/**
 * Delivery vs yard self-pickup. PIN create / PIN email / lock confirm must skip delivery.
 *
 * Primary flag: addons.isDelivery (and deliveryService). Also honor delivery_type and
 * always-delivered catalog services (dumpster #1, dump trailer with delivery #4) when
 * the JSON flag is missing.
 */

function asRecord(value: unknown): Record<string, unknown> {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        return parsed as Record<string, unknown>;
      }
    } catch {
      // ignore
    }
  }
  return {};
}

/** Catalog services that are always company delivery (not a yard padlock pickup). */
export const ALWAYS_DELIVERY_PLAN_IDS = [1, 4];

export function isDeliveryBooking(
  booking: Record<string, unknown> | null | undefined,
): boolean {
  if (!booking) return false;
  const addons = asRecord(booking.addons);
  const plan = asRecord(booking.plan);
  if (addons.isDelivery === true || addons.deliveryService === true) return true;
  if (booking.delivery_service === true) return true;
  if (String(booking.delivery_type || "").toLowerCase() === "delivery") return true;
  const planId = Number(plan.id);
  return ALWAYS_DELIVERY_PLAN_IDS.includes(planId);
}

/**
 * True when this booking should get a yard padlock PIN (create, confirm, email/SMS).
 * Delivery is always excluded, even if the plan name contains "trailer".
 */
export function bookingNeedsYardLockPin(
  booking: Record<string, unknown> | null | undefined,
): boolean {
  if (!booking || isDeliveryBooking(booking)) return false;
  const plan = asRecord(booking.plan);
  const name = String(plan.name ?? booking.service_name ?? "").toLowerCase();
  const serviceType = String(plan.service_type ?? booking.service_type ?? "");
  return (
    serviceType === "trailer_rental" ||
    Number(plan.id) === 2 ||
    Number(plan.id) === 5 ||
    name.includes("dump loader") ||
    name.includes("dump trailer") ||
    name.includes("trailer") ||
    plan.customer_pickup === true
  );
}

/**
 * Shared Igloohome bridge PIN helpers.
 *
 * A 201 from the bridge only means the job was queued. Deletes and creates must
 * be polled to completion or they silently block each other (bridge ≈ 2 jobs/min).
 * All helpers take a time budget so edge invocations stay under the ~150s gateway limit.
 */

const IGLOOHOME_API_BASE_URL = "https://api.igloodeveloper.co/igloohome";

export type JobState = "completed" | "failed" | "pending";

export type PollResult = {
  state: JobState;
  raw: unknown;
  polls: Array<Record<string, unknown>>;
};

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

function sleep(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

async function readResponse(res: Response) {
  const text = await res.text();
  try {
    return { text, json: text ? JSON.parse(text) : null };
  } catch {
    return { text, json: null };
  }
}

function isoNow() {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

/**
 * Poll an Igloohome job until completed/failed or the budget is exhausted.
 * Defaults: 2.5s between polls, ~45s total budget.
 */
export async function pollJob(
  accessToken: string,
  jobId: string,
  budgetMs = 45_000,
  delayMs = 2500,
): Promise<PollResult> {
  const polls: Array<Record<string, unknown>> = [];
  let raw: unknown = null;
  const deadline = Date.now() + budgetMs;
  let attempt = 0;

  while (Date.now() < deadline) {
    attempt += 1;
    await sleep(delayMs);
    if (Date.now() >= deadline && attempt > 1) break;

    const res = await fetch(`${IGLOOHOME_API_BASE_URL}/jobs/${jobId}`, {
      headers: { Authorization: `Bearer ${accessToken}`, Accept: "application/json" },
    });
    const body = await readResponse(res);
    raw = body.json ?? body.text;
    const jobResponse = body.json?.jobResponse;
    const jobStatus = jobResponse?.jobStatus;
    const completed = body.json?.completed;
    polls.push({
      attempt,
      httpStatus: res.status,
      completed: completed ?? null,
      jobStatus: jobStatus ?? null,
    });

    if (completed === true || jobStatus === 0) {
      return { state: "completed", raw, polls };
    }
    if (jobStatus === 2) {
      return { state: "failed", raw, polls };
    }
  }

  return { state: "pending", raw, polls };
}

/** Queue a jobType 5 delete and poll until the lock confirms removal. */
export async function deletePinVerified(
  accessToken: string,
  lockId: string,
  bridgeId: string,
  pin: string,
  budgetMs = 45_000,
): Promise<{ ok: boolean; jobId: string; state: JobState; polls: PollResult["polls"]; error?: string }> {
  const url = `${IGLOOHOME_API_BASE_URL}/devices/${lockId}/jobs/bridges/${bridgeId}`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({ jobType: 5, jobData: { pin } }),
  });
  const body = await readResponse(res);
  if (!res.ok && res.status !== 201) {
    return {
      ok: false,
      jobId: "",
      state: "failed",
      polls: [],
      error: `Delete failed HTTP ${res.status}: ${body.json?.error ?? body.text}`,
    };
  }
  const jobId = String(body.json?.jobId || body.json?.pinId || body.json?.id || "");
  if (!jobId) {
    // Some responses succeed without a jobId — treat as accepted but unverified.
    return { ok: false, jobId: "", state: "pending", polls: [], error: "Delete accepted but no jobId returned" };
  }
  const poll = await pollJob(accessToken, jobId, budgetMs);
  return {
    ok: poll.state === "completed",
    jobId,
    state: poll.state,
    polls: poll.polls,
    error: poll.state === "failed" ? "Lock rejected delete job" : undefined,
  };
}

/**
 * Delete every PIN we've issued for an order that still lacks lock_deleted_at.
 * Only stamps lock_deleted_at when the bridge confirms removal.
 * AlgoPIN rows are marked deleted in DB only (cannot remotely revoke).
 */
export async function clearKnownPins(
  supabase: SupabaseClient,
  accessToken: string,
  orderId: number,
  opts: {
    lockId: string;
    bridgeId: string;
    /** Max ms spent on all deletes combined. */
    budgetMs?: number;
    /** Settle pause between bridge jobs (Igloohome ~2/min). */
    settleMs?: number;
  },
): Promise<{
  attempted: number;
  confirmed: number;
  failed: number;
  pending: number;
  details: Array<Record<string, unknown>>;
}> {
  const budgetMs = opts.budgetMs ?? 60_000;
  const settleMs = opts.settleMs ?? 15_000;
  const deadline = Date.now() + budgetMs;
  const details: Array<Record<string, unknown>> = [];

  const { data: rows } = await supabase
    .from("rental_access_codes")
    .select("id, access_pin, pin_type, status, lock_deleted_at")
    .eq("order_id", orderId)
    .is("lock_deleted_at", null);

  let attempted = 0;
  let confirmed = 0;
  let failed = 0;
  let pending = 0;

  for (const row of rows || []) {
    if (Date.now() >= deadline) {
      pending += 1;
      details.push({ id: row.id, pin: row.access_pin, skipped: true, reason: "budget_exhausted" });
      continue;
    }

    if (row.pin_type === "algopin") {
      // Cannot remotely revoke AlgoPIN; mark DB as deleted so we don't keep trying.
      await supabase
        .from("rental_access_codes")
        .update({
          status: row.status === "active" ? "expired" : row.status,
          lock_deleted_at: new Date().toISOString(),
        })
        .eq("id", row.id);
      confirmed += 1;
      details.push({ id: row.id, pin: row.access_pin, pin_type: "algopin", state: "db_only" });
      continue;
    }

    if (!row.access_pin) continue;
    attempted += 1;
    const remaining = Math.max(5_000, deadline - Date.now());
    const perJobBudget = Math.min(45_000, remaining);
    const result = await deletePinVerified(
      accessToken,
      opts.lockId,
      opts.bridgeId,
      row.access_pin,
      perJobBudget,
    );
    details.push({
      id: row.id,
      pin: row.access_pin,
      jobId: result.jobId,
      state: result.state,
      error: result.error ?? null,
    });

    if (result.ok) {
      confirmed += 1;
      await supabase
        .from("rental_access_codes")
        .update({
          status: "expired",
          lock_deleted_at: new Date().toISOString(),
        })
        .eq("id", row.id);
    } else if (result.state === "failed") {
      failed += 1;
      // Still expire in DB so a new PIN can be issued; lock may need another clear later.
      await supabase
        .from("rental_access_codes")
        .update({ status: "expired" })
        .eq("id", row.id)
        .eq("status", "active");
    } else {
      pending += 1;
      await supabase
        .from("rental_access_codes")
        .update({ status: "expired" })
        .eq("id", row.id)
        .eq("status", "active");
    }

    // Settle between bridge jobs when more remain.
    if (Date.now() + settleMs < deadline && attempted < (rows || []).length) {
      await sleep(settleMs);
    }
  }

  return { attempted, confirmed, failed, pending, details };
}

/** Queue a jobType 4 custom-duration PIN and poll until the lock confirms. */
export async function createPinVerified(
  accessToken: string,
  lockId: string,
  bridgeId: string,
  pin: string,
  startDate: string,
  endDate: string,
  accessName: string,
  budgetMs = 60_000,
): Promise<{
  success: boolean;
  pin: string;
  jobId: string;
  state: JobState;
  polls: PollResult["polls"];
  raw: unknown;
  error?: string;
}> {
  const url = `${IGLOOHOME_API_BASE_URL}/devices/${lockId}/jobs/bridges/${bridgeId}`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      jobType: 4,
      jobData: { accessName, pin, pinType: 4, startDate, endDate },
    }),
  });
  const body = await readResponse(res);
  if (!res.ok && res.status !== 201) {
    return {
      success: false,
      pin,
      jobId: "",
      state: "failed",
      polls: [],
      raw: body.json ?? body.text,
      error: `Create failed HTTP ${res.status}: ${body.json?.error ?? body.text}`,
    };
  }
  const jobId = String(body.json?.jobId || body.json?.pinId || body.json?.id || "");
  if (!jobId) {
    return {
      success: false,
      pin,
      jobId: "",
      state: "pending",
      polls: [],
      raw: body.json,
      error: "Create accepted but no jobId returned",
    };
  }
  const poll = await pollJob(accessToken, jobId, budgetMs);
  return {
    success: poll.state === "completed",
    pin,
    jobId,
    state: poll.state,
    polls: poll.polls,
    raw: poll.raw,
    error: poll.state === "failed"
      ? "Lock rejected PIN create job"
      : poll.state === "pending"
        ? "Bridge has not confirmed PIN delivery yet"
        : undefined,
  };
}

export type EnsurePinResult = {
  success: boolean;
  pin: string;
  jobId: string;
  pinType: "bridge_proxied";
  startDate: string;
  endDate: string;
  lockConfirmed: boolean;
  clear: Awaited<ReturnType<typeof clearKnownPins>>;
  createState: JobState;
  polls: PollResult["polls"];
  error?: string;
};

/**
 * Clear known PINs (verified), then create a new bridge PIN and poll for confirmation.
 * Bounded: clear budget + create budget should stay under ~120s total.
 */
export async function ensurePinOnLock(
  supabase: SupabaseClient,
  accessToken: string,
  opts: {
    orderId: number;
    lockId: string;
    bridgeId: string;
    pin?: string;
    startDate: string;
    endDate: string;
    accessName: string;
    clearBudgetMs?: number;
    createBudgetMs?: number;
    settleMs?: number;
    /** When upgrading from AlgoPIN, do not expire the fallback until bridge confirms. */
    skipClear?: boolean;
  },
): Promise<EnsurePinResult> {
  const pin = opts.pin || String(Math.floor(Math.random() * 900000) + 100000);
  const emptyClear = { attempted: 0, confirmed: 0, failed: 0, pending: 0, details: [] as Array<Record<string, unknown>> };
  const clear = opts.skipClear
    ? emptyClear
    : await clearKnownPins(supabase, accessToken, opts.orderId, {
      lockId: opts.lockId,
      bridgeId: opts.bridgeId,
      budgetMs: opts.clearBudgetMs ?? 50_000,
      settleMs: opts.settleMs ?? 15_000,
    });

  // If a delete is still pending, wait a short settle then proceed — create may still
  // fail if the old PIN is on the lock, but the watchdog will retry.
  if (clear.pending > 0) {
    await sleep(opts.settleMs ?? 15_000);
  }

  const created = await createPinVerified(
    accessToken,
    opts.lockId,
    opts.bridgeId,
    pin,
    opts.startDate,
    opts.endDate,
    opts.accessName,
    opts.createBudgetMs ?? 60_000,
  );

  return {
    success: created.state === "completed",
    pin,
    jobId: created.jobId,
    pinType: "bridge_proxied",
    startDate: opts.startDate,
    endDate: opts.endDate,
    lockConfirmed: created.state === "completed",
    clear,
    createState: created.state,
    polls: created.polls,
    error: created.error,
  };
}

export { isoNow, IGLOOHOME_API_BASE_URL };

/**
 * Booking time slot parsing, mirroring the SQL functions of the same name.
 *
 * Stored slots come in four shapes depending on which code path wrote the row: '6:00 AM',
 * '06:00:00', '06:00:00|08:00:00' and '08:00|17:00'. Anything that reasons about booking times
 * has to handle all four, and previously each caller handled a different subset.
 *
 * Prefer the typed bookings.*_window_start / *_window_end columns where they are available;
 * these helpers exist for rows written before those columns existed and for callers that only
 * have the text value to hand.
 *
 * Keep in sync with public.parse_clock_time and public.parse_booking_time_slot.
 */

export const BUSINESS_TIME_ZONE = "America/Denver";

export type ClockTime = { hour: number; minute: number; second: number };
export type TimeWindow = { start: ClockTime; end: ClockTime };

const TWELVE_HOUR = /^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)$/i;
const TWENTY_FOUR_HOUR = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/;

/** Parses HH:mm, HH:mm:ss or h:mm AM/PM. Returns null for anything unrecognised. */
export function parseClockTime(value: string | null | undefined): ClockTime | null {
  if (typeof value !== "string") return null;
  const raw = value.trim();
  if (!raw) return null;

  const twelve = TWELVE_HOUR.exec(raw);
  if (twelve) {
    let hour = parseInt(twelve[1], 10) % 12;
    if (twelve[4].toUpperCase() === "PM") hour += 12;
    const minute = parseInt(twelve[2], 10);
    const second = twelve[3] ? parseInt(twelve[3], 10) : 0;
    if (minute > 59 || second > 59) return null;
    return { hour, minute, second };
  }

  const twentyFour = TWENTY_FOUR_HOUR.exec(raw);
  if (twentyFour) {
    const hour = parseInt(twentyFour[1], 10);
    const minute = parseInt(twentyFour[2], 10);
    const second = twentyFour[3] ? parseInt(twentyFour[3], 10) : 0;
    if (hour > 23 || minute > 59 || second > 59) return null;
    return { hour, minute, second };
  }

  return null;
}

function toMinutes(t: ClockTime): number {
  return t.hour * 60 + t.minute;
}

/**
 * Normalises any stored slot into a start/end window.
 *
 * @param spanMinutes How long a single-valued slot lasts. Pass 0 for services whose slot is an
 *   instant rather than a window (hourly self-pickup stores a collection time and a return-by
 *   deadline, not a window).
 */
export function parseBookingTimeSlot(
  slot: string | null | undefined,
  spanMinutes = 120,
): TimeWindow | null {
  if (typeof slot !== "string") return null;
  const raw = slot.trim();
  if (!raw) return null;

  if (raw.includes("|")) {
    const [leftRaw, rightRaw] = raw.split("|");
    const start = parseClockTime(leftRaw);
    const end = parseClockTime(rightRaw);
    if (!start || !end) return null;
    return { start, end };
  }

  const start = parseClockTime(raw);
  if (!start) return null;

  const span = Math.max(spanMinutes ?? 0, 0);
  if (span === 0) return { start, end: { ...start } };

  const endMinutes = toMinutes(start) + span;
  // A late slot plus its span can run past midnight, which would leave end before start and
  // break every overlap test. Clamp to the end of the day instead.
  if (endMinutes >= 24 * 60) {
    return { start, end: { hour: 23, minute: 59, second: 59 } };
  }
  return {
    start,
    end: { hour: Math.floor(endMinutes / 60), minute: endMinutes % 60, second: 0 },
  };
}

/** Minutes the given zone is offset from UTC at a particular instant (negative west of UTC). */
function zoneOffsetMinutes(instant: Date, timeZone: string): number {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour12: false,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(instant);

  const field = (type: string) => Number(parts.find((p) => p.type === type)?.value ?? "0");
  // Intl renders midnight as hour 24 in some runtimes; normalise it.
  const hour = field("hour") % 24;

  const asIfUtc = Date.UTC(
    field("year"),
    field("month") - 1,
    field("day"),
    hour,
    field("minute"),
    field("second"),
  );
  return (asIfUtc - instant.getTime()) / 60000;
}

/**
 * Converts a wall-clock date and time in the business timezone into a real UTC instant.
 *
 * The offset depends on the instant we are trying to find, so this resolves it in two passes:
 * guess using the offset at the naive instant, then re-check the offset at that result. That
 * matters because America/Denver is UTC-7 in winter and UTC-6 in summer, and the previous
 * implementation hardcoded a single offset.
 */
export function businessWallTimeToUtc(
  dateIso: string,
  time: ClockTime,
  timeZone: string = BUSINESS_TIME_ZONE,
): Date | null {
  const dateMatch = /^(\d{4})-(\d{2})-(\d{2})/.exec(dateIso ?? "");
  if (!dateMatch) return null;

  const naive = Date.UTC(
    Number(dateMatch[1]),
    Number(dateMatch[2]) - 1,
    Number(dateMatch[3]),
    time.hour,
    time.minute,
    time.second,
  );

  const firstOffset = zoneOffsetMinutes(new Date(naive), timeZone);
  let resolved = new Date(naive - firstOffset * 60000);

  const secondOffset = zoneOffsetMinutes(resolved, timeZone);
  if (secondOffset !== firstOffset) {
    resolved = new Date(naive - secondOffset * 60000);
  }
  return resolved;
}

/** Formats a ClockTime as HH:mm:ss, matching the Postgres `time` text representation. */
export function formatClockTime(time: ClockTime): string {
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(time.hour)}:${pad(time.minute)}:${pad(time.second)}`;
}

import {
  BUSINESS_TIME_ZONE,
  businessWallTimeToUtc,
  type ClockTime,
  parseBookingTimeSlot,
  parseClockTime,
} from "./parseBookingTimeSlot.ts";

export const PIN_LEAD_TIME_MS = 12 * 60 * 60 * 1000;
/** Extra hour the padlock PIN stays valid after the scheduled booking end. */
export const RETURN_GRACE_MS = 60 * 60 * 1000;
/** Activate the PIN this many ms before drop-off so it works the instant they arrive. */
export const PIN_EARLY_ACTIVATION_MS = 30 * 60 * 1000;
/** Second customer PIN message this many ms before drop-off. */
export const PIN_REMINDER_LEAD_MS = 60 * 60 * 1000;
/** Hourly AlgoPIN duration bounds (Igloohome). */
export const ALGOPIN_HOURLY_MIN_HOURS = 1;
export const ALGOPIN_HOURLY_MAX_HOURS = 672;
/** Igloohome will not delete an AlgoPIN whose start is more than 256 hours away. */
export const ALGOPIN_DELETE_LEAD_MS = 256 * 60 * 60 * 1000;
/** Booking statuses that must expire portal PIN access and retry lock delete. */
export const PIN_REVOKE_STATUSES = ["Cancelled", "cancellation_pending", "pending_review"] as const;

/** Calendar YYYY-MM-DD in the yard timezone. */
export function denverCalendarDate(now: Date = new Date()): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: BUSINESS_TIME_ZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const year = parts.find((p) => p.type === "year")?.value;
  const month = parts.find((p) => p.type === "month")?.value;
  const day = parts.find((p) => p.type === "day")?.value;
  return `${year}-${month}-${day}`;
}

export function addCalendarDays(ymd: string, days: number): string {
  const [year, month, day] = ymd.split("-").map(Number);
  const utc = Date.UTC(year, month - 1, day + days);
  return new Date(utc).toISOString().slice(0, 10);
}

/** Overnight lock programming: drop-off is today or tomorrow in Denver. */
export function isDropOffTodayOrTomorrow(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  const drop = booking.drop_off_date;
  if (!drop) return false;
  const today = denverCalendarDate(now);
  const tomorrow = addCalendarDays(today, 1);
  return drop === today || drop === tomorrow;
}

/** First PIN email/SMS: lock may already hold the code; customer is told from 12h before drop-off. */
export function isDueForFirstPinNotify(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.drop_off_date) return false;
  const { startMs, graceEndMs } = getBookingWindow(booking);
  if (!Number.isFinite(startMs) || !Number.isFinite(graceEndMs)) return false;
  const nowMs = now.getTime();
  return nowMs >= startMs - PIN_LEAD_TIME_MS && nowMs < graceEndMs;
}

/** 1-hour reminder: after the first PIN message, from 1h before drop-off until 15 minutes after it. */
export function isDueForPinReminder(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.drop_off_date) return false;
  const { startMs } = getBookingWindow(booking);
  if (!Number.isFinite(startMs)) return false;
  const nowMs = now.getTime();
  return nowMs >= startMs - PIN_REMINDER_LEAD_MS && nowMs < startMs + 15 * 60 * 1000;
}

/**
 * When a booking has no usable time at all, assume the yard's normal operating bounds. These
 * are business-local hours, not UTC: the previous implementation used UTC fallbacks, and the
 * end fallback of 05:00 UTC actually resolved to 11pm local on the day *before* pickup, which
 * made such bookings look finished before they began.
 */
const DEFAULT_START_LOCAL: ClockTime = { hour: 6, minute: 0, second: 0 };
const DEFAULT_END_LOCAL: ClockTime = { hour: 23, minute: 0, second: 0 };

export type BookingWindowFields = {
  drop_off_date?: string | null;
  drop_off_time_slot?: string | null;
  pickup_date?: string | null;
  pickup_time_slot?: string | null;
  /** Typed columns added in the time-window normalisation migration; preferred when present. */
  drop_off_window_start?: string | null;
  drop_off_window_end?: string | null;
  pickup_window_start?: string | null;
  pickup_window_end?: string | null;
};

/**
 * Resolve a booking-local wall time, preferring the typed column and falling back to parsing
 * the legacy text slot. `edge` picks which end of a window to use.
 */
function resolveLocalTime(
  typedValue: string | null | undefined,
  textSlot: string | null | undefined,
  edge: "start" | "end",
  fallback: ClockTime,
): ClockTime {
  const typed = parseClockTime(typedValue);
  if (typed) return typed;

  const parsed = parseBookingTimeSlot(textSlot, 0);
  if (parsed) return edge === "start" ? parsed.start : parsed.end;

  return fallback;
}

export function buildBookingDateUTC(
  date: string,
  timeSlot: string | null | undefined,
  fallbackLocalHour: number,
): string {
  const parsed = parseBookingTimeSlot(timeSlot, 0);
  const local = parsed?.start ?? { hour: fallbackLocalHour, minute: 0, second: 0 };
  const instant = businessWallTimeToUtc(date, local, BUSINESS_TIME_ZONE);
  if (!instant) {
    return `${date}T${String(fallbackLocalHour).padStart(2, "0")}:00:00+00:00`;
  }
  return instant.toISOString();
}

/** Add RETURN_GRACE_MS to an ISO date string and return a new ISO (+00:00) string. */
export function addGraceHour(isoDate: string): string {
  const ms = new Date(isoDate).getTime() + RETURN_GRACE_MS;
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

/**
 * AlgoPIN rejects starts that aren't whole-hour and rejects the JS `.000Z` suffix.
 * Required shape: `YYYY-MM-DDTHH:00:00+00:00`.
 */
export function formatAlgoPinStartIso(isoDate: string): string {
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return isoDate;
  d.setUTCMinutes(0, 0, 0);
  return d.toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

/**
 * Hourly AlgoPIN end: ceil to the next UTC hour so a partial hour is not cut short.
 * Already-on-the-hour values are left alone.
 */
export function formatAlgoPinEndIso(isoDate: string): string {
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return isoDate;
  if (d.getUTCMinutes() !== 0 || d.getUTCSeconds() !== 0 || d.getUTCMilliseconds() !== 0) {
    d.setUTCHours(d.getUTCHours() + 1);
  }
  d.setUTCMinutes(0, 0, 0);
  return d.toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

/**
 * Igloohome rejects a duration PIN whose startDate falls before the current hour.
 * Raises a past start up to the top of the current hour; leaves future starts alone.
 */
export function clampIgloohomeStart(isoDate: string, now: Date = new Date()): string {
  const hourFloor = new Date(now.getTime());
  hourFloor.setUTCMinutes(0, 0, 0);
  const ms = Math.max(new Date(isoDate).getTime(), hourFloor.getTime());
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

export function getBookingWindow(booking: BookingWindowFields) {
  const startLocal = resolveLocalTime(
    booking.drop_off_window_start,
    booking.drop_off_time_slot,
    "start",
    DEFAULT_START_LOCAL,
  );
  const endLocal = resolveLocalTime(
    booking.pickup_window_end ?? booking.pickup_window_start,
    booking.pickup_time_slot,
    "end",
    DEFAULT_END_LOCAL,
  );

  const startDate = businessWallTimeToUtc(booking.drop_off_date ?? "", startLocal);
  const endDate = businessWallTimeToUtc(booking.pickup_date ?? "", endLocal);

  const startMs = startDate ? startDate.getTime() : NaN;
  const endMs = endDate ? endDate.getTime() : NaN;
  const graceEndMs = endMs + RETURN_GRACE_MS;
  const graceEndIso = Number.isFinite(graceEndMs)
    ? new Date(graceEndMs).toISOString().replace(/\.\d{3}Z$/, "+00:00")
    : "";
  const activationMs = startMs - PIN_EARLY_ACTIVATION_MS;
  const activationIso = Number.isFinite(activationMs)
    ? new Date(activationMs).toISOString().replace(/\.\d{3}Z$/, "+00:00")
    : "";

  return {
    startMs,
    endMs,
    graceEndMs,
    pinEligibleFromMs: startMs - PIN_LEAD_TIME_MS,
    activationMs,
    activationIso,
    startIso: startDate ? startDate.toISOString() : "",
    endIso: endDate ? endDate.toISOString() : "",
    graceEndIso,
  };
}

/**
 * PIN start sent to Igloohome: booking drop-off minus 30 minutes, clamped to the
 * current hour so Igloohome accepts it. Customers still see the appointment time.
 */
export function getPinActivationStart(
  booking: BookingWindowFields,
  now: Date = new Date(),
): string {
  const { activationIso } = getBookingWindow(booking);
  return clampIgloohomeStart(activationIso, now);
}

/** Hour-aligned hourly AlgoPIN window: activation start → return + grace, ceiled. */
export function getHourlyAlgoPinWindow(
  booking: BookingWindowFields,
  now: Date = new Date(),
): { startDate: string; endDate: string } {
  const startDate = formatAlgoPinStartIso(getPinActivationStart(booking, now));
  const { graceEndIso } = getBookingWindow(booking);
  const endDate = formatAlgoPinEndIso(graceEndIso);
  return { startDate, endDate };
}

/** Scheduled return time with no grace — for all customer-facing copy. */
export function getCustomerVisibleEndIso(booking: BookingWindowFields): string {
  return getBookingWindow(booking).endIso;
}

export function isWithinPinGenerationWindow(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.drop_off_date || !booking.pickup_date) return false;
  const { pinEligibleFromMs, graceEndMs } = getBookingWindow(booking);
  if (!Number.isFinite(pinEligibleFromMs) || !Number.isFinite(graceEndMs)) return false;
  const nowMs = now.getTime();
  return nowMs >= pinEligibleFromMs && nowMs < graceEndMs;
}

/**
 * Hourly AlgoPIN may be minted only inside the 12h issue window, and never when
 * startDate is more than 256 hours away (Igloohome cannot delete those codes).
 */
export function canIssueHourlyAlgoPin(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!isWithinPinGenerationWindow(booking, now)) return false;
  const { startDate, endDate } = getHourlyAlgoPinWindow(booking, now);
  const startMs = new Date(startDate).getTime();
  const endMs = new Date(endDate).getTime();
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return false;
  if (startMs - now.getTime() > ALGOPIN_DELETE_LEAD_MS) return false;
  const hours = (endMs - startMs) / (60 * 60 * 1000);
  return hours >= ALGOPIN_HOURLY_MIN_HOURS && hours <= ALGOPIN_HOURLY_MAX_HOURS;
}

export function isBookingEnded(
  booking: BookingWindowFields,
  now: Date = new Date(),
): boolean {
  if (!booking.pickup_date) return false;
  const { graceEndMs } = getBookingWindow(booking);
  if (!Number.isFinite(graceEndMs)) return false;
  return now.getTime() >= graceEndMs;
}

export function getPinWindowSkipReason(
  booking: BookingWindowFields,
  now: Date = new Date(),
): "too_early" | "ended" | null {
  if (!booking.drop_off_date || !booking.pickup_date) return "too_early";
  const { pinEligibleFromMs, graceEndMs } = getBookingWindow(booking);
  if (!Number.isFinite(pinEligibleFromMs) || !Number.isFinite(graceEndMs)) return "too_early";
  const nowMs = now.getTime();
  if (nowMs < pinEligibleFromMs) return "too_early";
  if (nowMs >= graceEndMs) return "ended";
  return null;
}

/** The columns getBookingWindow needs, for edge functions building their booking selects. */
export const BOOKING_WINDOW_COLUMNS =
  "drop_off_date, pickup_date, drop_off_time_slot, pickup_time_slot, " +
  "drop_off_window_start, drop_off_window_end, pickup_window_start, pickup_window_end";

